    let view=s,mem=m;
    if(origin?.type==="card"){
      const pay=T.payment(s.dice,T.cardCost(s,origin,m));
      if(pay)view={...s,dice:pay.remaining,hand:T.indexedHand(s.hand.filter((_,i)=>i!==origin.index))};
      if(origin.id==="meditation")mem={...m,sleepy:m.sleepy+2};
    }
