        score=Math.max(score,1);
      if(retreat&&!sameFinish)score+=28;
      if(attacks.length&&!sameFinish&&currentAxis==="relay"&&T.team[who].name==="哥伦比娅"&&T.damageEstimate(next,m,who,"NA").enhancedReady)score+=10;
