    stars: "补充出战角色充能",
    calx: "转移后台充能",
    draw: "补充手牌",
    thundergrass: "选择后续使用的雷草祝佑",
    shatterbolt: "为后续元素爆发准备减费",
    sharpkernel: "为后续元素战技准备减费",
    lost: "接续本轮阵亡后的行动",
    toss: "重新投掷不合用的骰子",
    companion: "将骰子转为万能骰",
    sweet: "恢复目标角色生命",
    hashbrown: "恢复目标角色生命",
    lotus: "为下一次受伤提供减伤",
